# Create output grid
grid_out = [[0] * width_in for _ in range(height_out)]

# Extend 5 pattern: c = 9 + r
for r in range(height_out):
    c = 9 + r
    if 0 <= c < width_in:
        grid_out[r][c] = 5

# Extend 4 pattern: c = r - 2  (or more precisely: c = r - 2 starting from r=2)
for r in range(height_out):
    if r >= 2:
        c = r - 2
        if 0 <= c < width_in:
            grid_out[r][c] = 4

# Extend 3 pattern: pair (r-7, r-6) for r >= 9
for r in range(height_out):
    if r >= 9:
        left = r - 7
        right = r - 6
        if left < width_in and right < width_in:
            grid_out[r][left] = 3
